svg.script:
(function () {
  function updateDynamicPlate() {
    var digits = document.getElementById('t-digits');
    var plate = document.getElementById('c-plate');
    var grid = plate && plate.querySelector('.grid');
    var namebox = plate && plate.querySelector('.namebox');
    var name = plate && plate.querySelector('#t-name');
    if (!digits || !plate || !grid || !namebox || !name) return;

    var digitCount = (digits.textContent || '').replace(/\s/g, '').length || 1;
    var cellWidth = 115;
    var plateWidth = digitCount * cellWidth;
    grid.setAttribute('width', plateWidth);
    namebox.setAttribute('width', plateWidth);

    // Center the name on the actual, dynamically sized name box.
    name.setAttribute('x', plateWidth / 2);
    name.setAttribute('text-anchor', 'middle');
    name.removeAttribute('textLength');
    name.removeAttribute('lengthAdjust');
    name.removeAttribute('transform');
    var availableNameWidth = Math.max(20, plateWidth - 36);
    var measuredNameWidth = 0;
    try { measuredNameWidth = name.getComputedTextLength(); } catch (e) {}
    if (measuredNameWidth > availableNameWidth && measuredNameWidth > 0) {
      name.setAttribute('textLength', availableNameWidth);
      name.setAttribute('lengthAdjust', 'spacingAndGlyphs');
    }

    // Fit to the active layout's viewBox while retaining its center anchor.
    var layouts = document.querySelectorAll('.l');
    var layout = Array.prototype.find.call(layouts, function (item) {
      return getComputedStyle(item).display !== 'none';
    });
    if (!layout) return;
    var styles = getComputedStyle(layout);
    var viewBox = layout.viewBox && layout.viewBox.baseVal;
    var viewWidth = viewBox && viewBox.width ? viewBox.width : 1000;
    var maxScale = parseFloat(styles.getPropertyValue('--up')) || 1;
    var margin = viewWidth * 0.06;
    var scale = Math.min(maxScale, (viewWidth - margin * 2) / plateWidth);
    scale = Math.max(0.01, scale);
    plate.setAttribute('transform',
      'translate(' + (-plateWidth * scale / 2) + ' 0) scale(' + scale + ')');
  }

  function scheduleUpdate() {
    updateDynamicPlate();
    if (window.requestAnimationFrame) requestAnimationFrame(updateDynamicPlate);
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', scheduleUpdate);
  } else {
    scheduleUpdate();
  }
  window.addEventListener('load', scheduleUpdate);
  window.addEventListener('resize', scheduleUpdate);
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(scheduleUpdate);
})();
